import base64

# Paste your complete qr_code response here
qr_data = "data:image/png;base64,"

# Remove the data URL prefix
base64_data = qr_data.split(",", 1)[1]

# Decode and save the image
image_bytes = base64.b64decode(base64_data)

with open("nexora_mfa_qr.png", "wb") as image:
    image.write(image_bytes)

print("QR code saved as nexora_mfa_qr.png")
